import { AxisScale } from '@visx/axis';
import { PickD3Scale } from '@visx/scale';

import { getMagnifierLabel } from '../../../../core/components/crosshair/functions/getMagnifierLabel.js';
import {
  FormatterWithPrecision,
  TimeFormatter,
} from '../../../../core/types/formatter.js';
import { MouseCoordinate } from '../../../../core/types/overlays.js';
import type { TimeseriesUnit } from '../../../../core/types/timeseries.js';
import type { YAxisScales } from '../../../types/state.js';

/**
 * Creates axis labels based on the data the mouse X and Y position
 * @param xScale - x-axis scale
 * @param yScales - y-axis scales
 * @param mousePosition - [x, y] position of the mouse
 * @param units - value axis units
 * @param yFormatters - external formatter for y axes
 * @param xFormatter - external formatter for x axis
 * @returns x and y magnifiers labels
 */
export function generateLabels(
  xScale: AxisScale<number>,
  yScales: YAxisScales,
  mousePosition: MouseCoordinate,
  units: TimeseriesUnit[],
  yFormatters: FormatterWithPrecision[],
  xFormatter: TimeFormatter,
) {
  const xTime = (xScale as PickD3Scale<'time'>).invert(mousePosition.x);
  const [leftAxisUnit, rightAxisUnit] = units;
  const [leftFormatter, rightFormatter] = yFormatters;

  const xLabel = xFormatter(xTime);

  const yLabelLeft = getMagnifierLabel(
    leftAxisUnit,
    'y',
    leftFormatter,
    mousePosition,
    yScales.left?.scale as PickD3Scale<'linear'>,
  );

  const yLabelRight = getMagnifierLabel(
    rightAxisUnit,
    'y',
    rightFormatter,
    mousePosition,
    yScales.right?.scale as PickD3Scale<'linear'>,
  );

  return {
    left: yLabelLeft,
    right: yLabelRight,
    bottom: xLabel,
  };
}
